{
  "type": "object",
  "properties": {
    "relevante": { "type": "boolean", "description": "false somente se a conversa tiver apenas cumprimentos, agradecimentos ou confirmações" },
    "resumo": { "type": "string", "description": "2 a 5 frases para o assessor" },
    "assuntos": { "type": "array", "items": { "type": "string" }, "description": "Temas tratados, 2 a 6 palavras cada" },
    "pendencias": { "type": "array", "items": { "type": "string" }, "description": "O que o assessor precisa fazer além dos pedidos registrados" },
    "preferencias_novas": { "type": "array", "items": { "type": "string" }, "description": "Preferências declaradas que ainda não estão registradas" },
    "oportunidades": { "type": "array", "items": { "type": "string" }, "description": "Ganchos de relacionamento citados pelo cliente, sem recomendação de investimento" },
    "requer_atencao": { "type": "boolean" },
    "motivo_atencao": { "type": "string", "description": "Uma frase quando requer_atencao for true; vazio caso contrário" }
  },
  "required": ["relevante", "resumo", "assuntos", "pendencias", "preferencias_novas", "oportunidades", "requer_atencao", "motivo_atencao"]
}

