// Decide o destinatário e monta o e-mail do assessor a partir do resumo da IA.
const cfg = $('Config: resumo ao assessor').first().json;
const prep = $('Preparar resumo').first().json;
const daLista = $('Buscar e-mail do assessor').first().json.assessor || null;

// Saída do resumo da IA (tolera o objeto aninhado em "output" ou em texto JSON)
let ia = $input.first().json;
ia = ia.output ?? ia;
if (ia && typeof ia.output === 'object' && ia.output !== null) ia = ia.output;
if (typeof ia === 'string') {
  try { ia = JSON.parse(ia); } catch (e) { ia = { resumo: ia }; }
}
const itens = (v) => (Array.isArray(v) ? v.map((x) => String(x ?? '').trim()).filter(Boolean) : []);
const r = {
  relevante: ia.relevante !== false,
  resumo: String(ia.resumo ?? '').trim(),
  assuntos: itens(ia.assuntos),
  pendencias: itens(ia.pendencias),
  preferencias_novas: itens(ia.preferencias_novas),
  oportunidades: itens(ia.oportunidades),
  requer_atencao: ia.requer_atencao === true,
  motivo_atencao: String(ia.motivo_atencao ?? '').trim(),
};
const pedidos = prep.pedidos || [];
const relevante = r.relevante || pedidos.length > 0 || r.requer_atencao;

// Destinatário único: o e-mail central do resumo. O assessor é identificado pelo Base44 e aparece no conteúdo.
const emailOk = (e) => /^[^@\s<>,;]+@[^@\s<>,;]+\.[^@\s<>,;]+$/.test(String(e ?? '').trim());
const nomeAssessor = prep.assessor_responsavel || '';
let para = String(cfg.email_resumo ?? '').trim();
const motivo = '';
const statusEnvio = 'enviado';

const destinoTeste = String(cfg.redirecionar_todos_para ?? '').trim();
const destinoReal = para;
if (destinoTeste) para = destinoTeste;

let enviar = true;
let statusFinal = 'enviando';
let observacao = motivo ? `Foi para o e-mail alternativo: ${motivo}.` : '';
if (!relevante && !cfg.enviar_conversas_triviais) {
  enviar = false;
  statusFinal = 'ignorado';
  observacao = 'Conversa só com cumprimentos ou agradecimentos.';
} else if (!emailOk(para)) {
  enviar = false;
  statusFinal = 'sem_destinatario';
  observacao = `Sem destinatário: ${motivo || 'e-mail inválido'}; configure email_resumo no nó Config.`;
} else if (destinoTeste) {
  observacao = `Modo de teste: enviado para ${destinoTeste} (destino real: ${destinoReal || 'nenhum'}). ${observacao}`.trim();
}
if (!enviar) para = '';

// ---------- E-mail ----------
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const rico = (s) => esc(s).replace(/\*([^*\n]+)\*/g, '<strong>$1</strong>').replace(/\n/g, '<br>');
const FONTE = 'font-family:Arial,Helvetica,sans-serif;';

const nome = prep.cliente?.nome || 'Cliente';
const n = pedidos.length;
let assunto = `Concierge · ${nome} · ${n ? `${n} ${n === 1 ? 'pedido' : 'pedidos'} · ` : ''}conversa de ${prep.quando}`;
if (r.requer_atencao) assunto = `[Atenção] ${assunto}`;
if (destinoTeste) assunto = `[Teste] ${assunto}`;

const bloco = (conteudo, topo = 20) => `<tr><td style="padding:${topo}px 28px 0;${FONTE}">${conteudo}</td></tr>`;
const secao = (titulo, corpo) => (corpo ? bloco(`<h2 style="margin:0 0 8px;font-size:15px;line-height:1.3;color:#14213d;">${esc(titulo)}</h2>${corpo}`) : '');
const lista = (linhas) => (linhas.length ? `<ul style="margin:0;padding-left:20px;font-size:14px;line-height:1.5;color:#1f2937;">${linhas.map((l) => `<li style="margin:0 0 6px;">${l}</li>`).join('')}</ul>` : '');
const aviso = (html, fundo, borda, cor) => bloco(`<div style="background:${fundo};border-left:4px solid ${borda};padding:12px 14px;font-size:14px;line-height:1.5;color:${cor};">${html}</div>`, 16);

const detalhes = [prep.cliente?.conta ? `Conta ${esc(prep.cliente.conta)}` : '', esc(prep.cliente?.categoria || ''), nomeAssessor ? `Assessor: ${esc(nomeAssessor)}` : 'Assessor não identificado'].filter(Boolean).join(' · ');
const qtd = (prep.mensagens || []).length;

const MAX = Number(cfg.max_mensagens_no_email) || 60;
const todas = prep.mensagens || [];
const omitidas = Math.max(0, todas.length - MAX);
const linhasConversa = todas.slice(-MAX).map((m) => {
  const doCliente = m.autor === 'Cliente';
  return `<tr>`
    + `<td style="padding:8px 10px;vertical-align:top;width:60px;font-size:12px;color:#5b6472;white-space:nowrap;${FONTE}">${esc(m.rotulo)}</td>`
    + `<td style="padding:8px 10px;font-size:13px;line-height:1.5;color:#1f2937;${doCliente ? 'background:#f3f6fa;' : ''}${FONTE}">`
    + `<strong style="color:${doCliente ? '#14213d' : '#1d4e89'};">${esc(m.autor)}</strong><br>${rico(String(m.texto).slice(0, 3000))}</td>`
    + `</tr>`;
}).join('');

const html = `<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(assunto)}</title></head>
<body style="margin:0;padding:0;background:#f4f6f9;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f6f9;"><tr><td align="center" style="padding:24px 12px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#ffffff;border:1px solid #e3e8ef;border-radius:8px;">
${bloco(`<div style="font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:#5b6472;">Concierge · resumo da conversa</div>`
  + `<h1 style="margin:8px 0 6px;font-size:22px;line-height:1.25;color:#14213d;">${esc(nome)}</h1>`
  + (detalhes ? `<div style="font-size:14px;color:#1f2937;">${detalhes}</div>` : '')
  + `<div style="margin-top:4px;font-size:13px;color:#5b6472;">Conversa no WhatsApp em ${esc(prep.periodo)} · ${qtd} ${qtd === 1 ? 'mensagem' : 'mensagens'}</div>`
  + (r.assuntos.length ? `<div style="margin-top:4px;font-size:13px;color:#5b6472;">Assuntos: ${r.assuntos.map(esc).join(' · ')}</div>` : ''), 24)}
${destinoTeste ? aviso(`<strong>Modo de teste.</strong> Em produção este e-mail iria para ${esc(destinoReal || 'ninguém')}.`, '#eef2ff', '#4f46e5', '#312e81') : ''}
${motivo ? aviso(`<strong>Encaminhe ao assessor responsável.</strong> Este resumo veio para o e-mail alternativo porque ${esc(motivo)}.`, '#fef7e0', '#b7791f', '#744210') : ''}
${r.requer_atencao ? aviso(`<strong>Ponto de atenção:</strong> ${esc(r.motivo_atencao || 'veja o resumo abaixo')}`, '#fdf1e7', '#c2410c', '#7c2d12') : ''}
${secao('Resumo', r.resumo ? `<p style="margin:0;font-size:14px;line-height:1.6;color:#1f2937;">${rico(r.resumo)}</p>` : '')}
${secao('Pedidos registrados', lista(pedidos.map((p) => `<strong>${esc(p.descricao)}</strong>${p.resumo ? `<br><span style="color:#5b6472;">${esc(p.resumo)}</span>` : ''}${p.rotulo ? ` <span style="color:#5b6472;">· ${esc(p.rotulo)}</span>` : ''}`)))}
${secao('Pendências', lista(r.pendencias.map(esc)))}
${secao('Preferências declaradas', r.preferencias_novas.length ? lista(r.preferencias_novas.map(esc)) + `<p style="margin:4px 0 0;font-size:12px;color:#5b6472;">Já salvas na memória do Concierge.</p>` : '')}
${secao('Oportunidades de relacionamento', lista(r.oportunidades.map(esc)))}
${secao('Conversa completa', linhasConversa
  ? (omitidas ? `<p style="margin:0 0 8px;font-size:12px;color:#5b6472;">${omitidas} mensagens anteriores omitidas.</p>` : '')
    + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e3e8ef;border-radius:6px;border-collapse:separate;">${linhasConversa}</table>`
  : '')}
${bloco(`<p style="margin:0;padding:16px 0 24px;border-top:1px solid #e3e8ef;font-size:12px;line-height:1.5;color:#5b6472;">Mensagem automática do Concierge. Este e-mail não chega ao cliente: retorne pelos canais habituais. Uso interno, com dados de cliente; não encaminhe para fora da corretora. Ref. ${esc(prep.notificacao_id)}</p>`, 24)}
</table>
</td></tr></table>
</body></html>`;

const resumoMemoria = [
  r.resumo,
  pedidos.length ? `Pedidos registrados: ${pedidos.map((p) => p.descricao).join('; ')}.` : '',
  r.pendencias.length ? `Pendências: ${r.pendencias.join('; ')}.` : '',
].filter(Boolean).join(' ');

return [{
  json: {
    enviar,
    status_final: statusFinal,
    status_envio: statusEnvio,
    para,
    assunto,
    html,
    observacao,
    assessor_responsavel: nomeAssessor,
    salvar_memoria: relevante,
    resumo_json: JSON.stringify(r),
    resumo_memoria: resumoMemoria,
    preferencias_json: JSON.stringify(r.preferencias_novas),
  },
}];

// Organiza os pedidos do cliente que ainda não foram avisados ao assessor.
const grupo = $input.first().json;

const FUSO = 'America/Sao_Paulo';
const quando = (v) => (v
  ? new Intl.DateTimeFormat('pt-BR', { timeZone: FUSO, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(v))
  : '');

// Defesa: pedidos que mencionam movimentação financeira chegam marcados e com o aviso de que não valem como ordem.
const ALERTA = /(resgat|\bsaque\b|\bsacar\b|\bpix\b|\bted\b|conta corrente|ordem de (compra|venda|resgate|aplica)|transfer\S*\s+(\S+\s+){0,2}(dinheiro|recursos?|valor(es)?|saldo|investimentos?|aplica\S*|patrim\S*|carteira)|\baplica(ção|cao|ções|coes)\b(?!\s+d[oa]s?\s+(desconto|benef|cupom|c[oó]digo|voucher))|aplicar\s+(\S+\s+){0,2}(dinheiro|recursos?|em\s+(fundo|cdb|lci|lca|tesouro|a[cç][oõ]es|renda|previd|cripto|cotas?))|r\$\s?\d{2,3}(\.\d{3})+|r\$\s?\d{5,}|r\$\s?\d+([.,]\d+)?\s?(mil\b|milh|bilh)|\d+([.,]\d+)?\s?(mil|milh\S*|bilh\S*)\s+(de\s+)?reais)/i;
const AVISO_ORDEM = 'Pedido recebido pelo Concierge: não vale como ordem de resgate, transferência ou aplicação. Confirme diretamente com o cliente pelos canais oficiais.';

const pedidos = (grupo.pedidos || []).map((p) => {
  const descricao = String(p.descricao ?? '').trim();
  const resumo = String(p.resumo ?? '').trim();
  const alerta = ALERTA.test(`${descricao} ${resumo}`);
  return {
    id: p.id,
    tipo: p.tipo === 'falar_com_assessor' ? 'falar_com_assessor' : 'pedido',
    descricao: alerta ? `[Atenção] ${descricao}` : descricao,
    resumo: alerta ? `${resumo}${resumo ? '\n' : ''}${AVISO_ORDEM}` : resumo,
    contato_preferido: String(p.contato_preferido ?? '').trim(),
    quando: quando(p.em),
    alerta,
  };
});

// WhatsApp usado na conversa, no formato +55 61 99999-9999 quando o número é brasileiro.
const d = String(grupo.wa_from ?? '').replace(/\D/g, '');
const whatsapp = d.startsWith('55') && (d.length === 12 || d.length === 13)
  ? `+55 ${d.slice(2, 4)} ${d.slice(4, -4)}-${d.slice(-4)}`
  : (d ? `+${d}` : '');

return [{
  json: {
    cliente_id: grupo.cliente_id,
    pedido_ids_json: JSON.stringify((grupo.pedido_ids || []).map(String)),
    pedidos,
    quer_falar: pedidos.some((p) => p.tipo === 'falar_com_assessor'),
    whatsapp,
  },
}];

// Monta o aviso de pedidos para o WhatsApp centralizado do suporte (mesma estrutura do antigo e-mail).
const cfg = $('Config: resumo ao assessor').first().json;
const prep = $('Preparar aviso').first().json;
const base44 = $('Dados do cliente para o aviso (Base44)').first().json || {};

// Procura o campo no primeiro nível da resposta do Base44 ou em objetos aninhados (ex.: { cliente: {...} }).
function campo(obj, nomes, nivel = 0) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj) || nivel > 3) return '';
  for (const nome of nomes) {
    const v = obj[nome];
    if (v !== undefined && v !== null && typeof v !== 'object' && String(v).trim() !== '') return String(v).trim();
  }
  for (const v of Object.values(obj)) {
    const achado = campo(v, nomes, nivel + 1);
    if (achado) return achado;
  }
  return '';
}

const contextoOk = !base44.error && base44.encontrado !== false && Object.keys(base44).length > 0;
const CATEGORIAS = { bronze: 'Bronze', prata: 'Prata', ouro: 'Ouro', legado: 'Diamante', diamante: 'Diamante' };
const cliente = {
  nome: contextoOk ? campo(base44, ['nome_completo', 'full_name']) || campo(base44, ['primeiro_nome']) : '',
  categoria: contextoOk ? CATEGORIAS[campo(base44, ['level', 'nivel']).toLowerCase()] || '' : '',
};
const nomeAssessor = contextoOk ? campo(base44, ['assessor_responsavel']) : '';

// Destinatário: WhatsApp centralizado do suporte (ou o número de teste, se configurado).
const numero = (v) => String(v ?? '').replace(/\D/g, '');
let para = numero(cfg.whatsapp_suporte);
const destinoTeste = numero(cfg.redirecionar_aviso_para);
const destinoReal = para;
if (destinoTeste) para = destinoTeste;
const enviar = para.length >= 10;
const observacao = !enviar
  ? 'Sem destinatário: configure whatsapp_suporte no nó Config.'
  : (destinoTeste ? `Modo de teste: enviado para ${destinoTeste} (destino real: ${destinoReal || 'nenhum'}).` : '');

// Campos do aviso. Parâmetros de modelo da Meta não aceitam quebra de linha nem valor vazio.
const linha = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const pedidos = prep.pedidos || [];
const descricoes = pedidos.map((p) => linha(p.tipo === 'falar_com_assessor'
  ? `Quer falar com o assessor: ${p.descricao || 'sem descrição'}`
  : (p.descricao || 'Pedido sem descrição')));
const contatos = [...new Set(pedidos.map((p) => linha(p.contato_preferido)).filter(Boolean))];
const campos = {
  cliente: linha(cliente.nome) || 'Cliente',
  categoria: linha(cliente.categoria) || '-',
  whatsapp: linha(prep.whatsapp) || '-',
  assessor: linha(nomeAssessor) || 'não identificado',
  pedido: descricoes.join(' | ') || '-',
  detalhes: pedidos.map((p) => linha(p.resumo)).filter(Boolean).join(' | ') || '-',
  contato: contatos.join('; ') || '-',
  quando: linha(pedidos.map((p) => p.quando).filter(Boolean)[0]) || '-',
};
for (const k of Object.keys(campos)) campos[k] = campos[k].slice(0, 300);

const texto = [
  `*Concierge · ${pedidos.length > 1 ? 'Novos pedidos' : 'Novo pedido'}*${destinoTeste ? ' [Teste]' : ''}`,
  '',
  `*Cliente:* ${campos.cliente}`,
  `*Categoria:* ${campos.categoria}`,
  `*WhatsApp do cliente:* ${campos.whatsapp}`,
  `*Assessor:* ${campos.assessor}`,
  '',
  `*Pedido:* ${campos.pedido}`,
  `*Detalhes:* ${campos.detalhes}`,
  `*Melhor contato:* ${campos.contato}`,
  `*Registrado em:* ${campos.quando}`,
  '',
  'Pedidos recebidos pelo Concierge não valem como ordem de resgate, transferência ou aplicação.',
].join('\n');

// Fora da janela de 24 h, a Meta só aceita modelo aprovado; texto livre serve para testes.
const usarModelo = cfg.aviso_usar_modelo === true;
const corpo = usarModelo
  ? {
      messaging_product: 'whatsapp',
      to: para,
      type: 'template',
      template: {
        name: String(cfg.modelo_aviso_nome || 'novo_pedido_concierge'),
        language: { code: String(cfg.modelo_aviso_idioma || 'pt_BR') },
        components: [{
          type: 'body',
          parameters: [campos.cliente, campos.categoria, campos.whatsapp, campos.assessor, campos.pedido, campos.detalhes, campos.contato, campos.quando]
            .map((t) => ({ type: 'text', text: t })),
        }],
      },
    }
  : { messaging_product: 'whatsapp', to: para, type: 'text', text: { preview_url: false, body: texto } };

return [{
  json: {
    enviar,
    status_envio: 'enviado',
    para,
    corpo,
    texto,
    observacao,
    assessor_responsavel: nomeAssessor,
    pedido_ids_json: prep.pedido_ids_json,
  },
}];

