// Defesa: revisa a saída da IA do resumo antes de montar o e-mail e salvar a memória.
const ALERTA = /(resgat|\bsaque\b|\bsacar\b|\bpix\b|\bted\b|conta corrente|ordem de (compra|venda|resgate|aplica)|transfer\S*\s+(\S+\s+){0,2}(dinheiro|recursos?|valor(es)?|saldo|investimentos?|aplica\S*|patrim\S*|carteira)|\baplica(ção|cao|ções|coes)\b(?!\s+d[oa]s?\s+(desconto|benef|cupom|c[oó]digo|voucher))|aplicar\s+(\S+\s+){0,2}(dinheiro|recursos?|em\s+(fundo|cdb|lci|lca|tesouro|a[cç][oõ]es|renda|previd|cripto|cotas?))|r\$\s?\d{2,3}(\.\d{3})+|r\$\s?\d{5,}|r\$\s?\d+([.,]\d+)?\s?(mil\b|milh|bilh)|\d+([.,]\d+)?\s?(mil|milh\S*|bilh\S*)\s+(de\s+)?reais)/i;
const PROIBIDO = /(instru|regra|prompt|sistema|ignor|permit|autoriz|pode (comentar|falar|informar|recomendar)|invest|carteira|resgat|transfer|aplica|ordem|senha|conta corrente|\bpix\b|\bted\b|r\$)/i;
const prep = $('Preparar resumo').first().json;

let saida = $input.first().json;
saida = saida.output ?? saida;
if (saida && typeof saida.output === 'object' && saida.output !== null) saida = saida.output;
if (typeof saida === 'string') {
  try { saida = JSON.parse(saida); } catch (e) { saida = { resumo: saida }; }
}
saida = { ...saida };

// Preferências: só gostos e hábitos curtos, nunca instruções ou permissões para o agente.
saida.preferencias_novas = (Array.isArray(saida.preferencias_novas) ? saida.preferencias_novas : [])
  .map((p) => String(p ?? '').trim())
  .filter((p) => p && p.length <= 150 && !PROIBIDO.test(p));

// Atenção por palavras-chave na fala do cliente e nos pedidos, independente do que a IA concluiu.
const texto = (prep.mensagens || []).filter((m) => m.autor === 'Cliente').map((m) => m.texto)
  .concat((prep.pedidos || []).map((p) => `${p.descricao} ${p.resumo}`)).join('\n');
if (ALERTA.test(texto)) {
  saida.requer_atencao = true;
  const aviso = 'Menção a movimentação financeira. Pedidos de resgate, transferência, aplicação ou ordem recebidos pelo Concierge não valem como instrução; confirme diretamente com o cliente pelos canais oficiais.';
  saida.motivo_atencao = saida.motivo_atencao ? `${saida.motivo_atencao} ${aviso}` : aviso;
}

return [{ json: { output: saida } }];

// Junta as falhas que ainda não foram alertadas: o Redis devolve 1 só na primeira vez de cada item e status.
const falhas = $('Há falhas para alertar?').all().map((i) => i.json);
const contagens = $input.all().map((i) => Number(Object.values(i.json)[0]));
const novas = falhas.filter((f, i) => contagens[i] === 1);
if (!novas.length) return [];
const linhas = novas.map((f) => {
  const oque = f.tipo === 'resumo' ? 'Resumo' : 'Aviso de pedido';
  const estado = f.status === 'sem_destinatario' ? 'sem destinatário' : `${f.status} após ${f.tentativas} tentativa(s)`;
  return `${oque} ${f.id} (cliente ${f.cliente_id}): ${estado}. ${f.detalhe || ''}`.trim();
});
const titulo = novas.length === 1 ? '1 envio ao assessor não saiu' : `${novas.length} envios ao assessor não saíram`;
return [{ json: { mensagem: `${titulo}: ${linhas.join(' | ')}`.slice(0, 3000) } }];

